#!/bin/bash
# R2 (PREREG_nature.md): 30 extra CAFE5 tip-permutation nulls (nullp11-40) per clade, Porifera excluded;
# Mollusca / Actinopteri_m (rescued fits) only once work/cafe/CAFE_RESCUE.DONE exists (second pass, same script).
# Lambda trees regenerated by 49_cafe_prep.py --nperm 40 into a scratch dir; deep and nullp1-10 must be identical to the
# originals (checked by md5) or the clade is skipped. Fits use the original counts.tsv, tree.nwk and base_e error model.
B=$HOME/deepsea_conv; cd $B || exit 0
PY=envs/dc/bin/python; CAFE=envs/dc/bin/cafe5; O=work/addon/R2/cafe_perm; mkdir -p $O
CL="Chondrichthyes Arthropoda Echinodermata Cnidaria Annelida"
[ -f work/cafe/CAFE_RESCUE.DONE ] && CL="$CL Mollusca Actinopteri"
: > $O/jobs.txt
for C in $CL; do
  D=work/cafe/$C; P=$O/$C; mkdir -p $P/prep $P/logs
  [ -s $P/prep/lambda_nullp40.nwk ] || $PY scripts/49_cafe_prep.py $C --out $P/prep --nperm 40 > $P/logs/prep.log 2>&1
  ok=1
  for f in tree.nwk lambda_deep.nwk $(cd $D && ls lambda_nullp*.nwk); do
    cmp -s $D/$f $P/prep/$f || { echo "$C $f differs" >> $O/check.txt; ok=0; }
  done
  [ $ok = 1 ] || continue
  E=$D/base_e/Base_error_model.txt; [ -s $E ] && E="-e$E" || E=""
  # rescued clades: use the rescue inputs if present
  CT=$D/counts.tsv; [ -s $D/rescue/counts.tsv ] && CT=$D/rescue/counts.tsv
  for k in $(seq 11 40); do
    echo "[ -s $P/nullp$k/Base_results.txt ] || nice -n 10 $CAFE -i $CT -t $D/tree.nwk -c 2 -o $P/nullp$k -y $P/prep/lambda_nullp$k.nwk $E > $P/logs/nullp$k.log 2>&1" >> $O/jobs.txt
  done
done
echo "$(date +%F_%T) clades: $CL; jobs $(wc -l < $O/jobs.txt)" >> $O/run.log
cat $O/jobs.txt | xargs -P 24 -I{} bash -c "{} < /dev/null"
echo "$(date +%F_%T) done" >> $O/run.log
touch $O/PASS1.DONE
exit 0
